arguments.command:
python -c "
from funcy.decorators import decorator, has_single_arg

def f(a, *, b):
    pass

print('has_single_arg:', has_single_arg(f))

@decorator
def my_dec(call):
    return call()

try:
    @my_dec
    def test(a, *, b):
        pass
    print('Works')
except Exception as e:
    print('Error:', e)
"
